/* eslint-disable no-nested-ternary */
import React, { useState } from 'react';
import { ArrowRightOutlined } from '@ant-design/icons';
import { Button } from 'antd';
import { axiosInstance } from 'services/globalInstance'
import Router from 'next/router'
import { showIntercom } from 'Utils/constants/index'
import NewRequestQuoteForm from 'components/features/setting/Quote/PlanBasedPricingPopup/NewRequestQuoteForm';

const commonMessage = `Please reach out to sales@uxcam.com to activate your account.`
const HelpLink = React.memo(({ id }) => {
  const isTrial = id === 'isTrial';
  return (
    <Button
      type={isTrial ? 'text' : 'primary'}
      style={{ color: isTrial ? '#5D97FF' : '#ffffff', marginTop: !isTrial ? '10px' : ''}}
      onClick={() => showIntercom()}
    >
      {isTrial ? (
        'Contact Sales'
      ) : (
        <>
          Need help? Get in touch <ArrowRightOutlined />
        </>
      )}
    </Button>
  );
} );

const getOrgCsrf = () => axiosInstance
    .get(`${process.env.API_URL  }/organization/csrf`, {
      withCredentials: true,
      validateStatus (status) {
        return status >= 200 && status < 401 // default
      },
    })
    .then((response) => response.data.data.csrf.token)
    .catch((error) => {
      if (error.response.data.error.status === 401) {
        window.location.href = `${process.env.REDIRECT_URL  }/login`
      }
      return error.response
    })
export const Common = ({ headerMsg, msg, imgSrcLink, id, isSrcElement }) => {
  const [orgCsrf, _getOrgCsrf] = useState(false)
  const [showRequestPricing, setShowRequestPricing] = useState(false)

  return (
    <div
      className={
        id === 'isTrial' ? 'message-box trial-end-message-box' : 'message-box'
      }
    >
      <div className='message-body-box'>
        <div className='icon-box'>
         {isSrcElement ? imgSrcLink :  <img src={imgSrcLink || '/static/icon-inactive.svg'} />}
        </div>
        <h2>{headerMsg || 'Your account is currently inactive.'}</h2>
      </div>
      <p>{msg || ''}</p>
      {id === 'isTrial' ? (
        <>
          <Button
            className='ant-btn-gradient'
            onClick={async () => {
              const orgCsrf = await getOrgCsrf()
              orgCsrf && (await _getOrgCsrf(orgCsrf))
              setShowRequestPricing(true)
            }}
          >
            Request a quote
          </Button>
          <p>
            {' or '} <br />
            <HelpLink id={id} />
          </p>
          <NewRequestQuoteForm setShowPricingModal={setShowRequestPricing} showPricingModal={showRequestPricing}/>
        </>
      ) : id === 'isLogin' ? (
        <a
          className="ant-btn ant-btn-gradient"
          onClick={() => Router.push('/login')}
        >
          Login
        </a>
      ) : (
        <HelpLink />
      )}
    </div>
  )
}
const mappedObj = {
  'invalid-email-address': (
    <Common
      msg={`A valid company email is required to access UXCam. ${commonMessage}`}
    />
  ),
  'reach-sales': (
    <Common
      msg="Please reach out to sales@uxcam.com to activate your account"
    />
  ),
  'reach-team': <Common msg="Please reach out to team@uxcam.com" />,
  'activation-needed': (
    <Common
      headerMsg="We have sent you an activation link."
      msg="Please check your email and click the link to activate your account."
      imgSrcLink="/static/icon-check-email.svg "
    />
  ),
  'reach-finance': (
    <Common
      msg="Please reach out to finance@uxcam.com to discuss your account"
    />
  ),
}
const DashboardAccess = ({
  direct,
  headerMsg,
  imgSrcLink,
  reasonNoDashboardAccess,
  id,
  isSrcElement
}) => (
    <div className='dashboard-restriction-wrapper'>
      <div className='message-wrapper'>
        {direct ? (
          <Common
            headerMsg={headerMsg}
            msg={reasonNoDashboardAccess}
            imgSrcLink={imgSrcLink}
            id={id}
            isSrcElement={isSrcElement}
          />
        ) : Object.keys(mappedObj).includes(reasonNoDashboardAccess) ? (
          mappedObj[reasonNoDashboardAccess]
        ) : id === 'isTrial' ? (
          <Common
            headerMsg={reasonNoDashboardAccess}
            id={id}
            imgSrcLink="/static/icon-sad.svg"
          />
        ) : (
          <Common msg={reasonNoDashboardAccess} />
        )}
      </div>
      <style>
        {`
          .dashboard-restriction-wrapper .message-wrapper .message-box{
            text-align: center;
            display: block;
            width: 500px;
            padding: 50px 20px
          }
          .dashboard-restriction-wrapper .message-wrapper .message-box .icon-box{
            width: 50px;
            margin: 0 auto 20px;
          }
          .dashboard-restriction-wrapper .message-wrapper .message-box .icon-box img{
            max-width: 100%;
          }
          .dashboard-restriction-wrapper .message-wrapper .message-box .anticon{
            font-size: 14px;
          }
        `}
      </style>
    </div>
  )
export default DashboardAccess
